// Self-checking testbench. Per-test files (ext.hex, dprog.hex, cprog.hex, expc.hex, meta.vh) are
// generated by `python3 -m armse.rtlexport` from the verified Python model.
// PASS  = result matrix bit-exact + bytes read/written + transfer count + zero bank conflicts.
// CYCLES line compares measured cycles with the Python model (informational unless +STRICT_CYC).
`timescale 1ns/1ps
`include "meta.vh"
`include "armse_fields.vh"
module tb_armse;
    reg clk = 1'b0, rst = 1'b1, go = 1'b0;
    always #5 clk = ~clk;

    reg h_we = 1'b0, h_sel = 1'b0;
    reg [15:0] h_addr = 16'd0;
    reg [127:0] h_wdata = 128'd0;
    wire busy, done;
    wire [31:0] cycles, cmp_busy, cmp_wait, dma_busy, dma_wait, bytes_rd, bytes_wr, n_xfer, conflicts;

    wire x_cmd_valid, x_cmd_write, x_wvalid;
    wire [31:0] x_cmd_addr, x_wdata;
    wire [7:0] x_cmd_beats;

    // ---------------- external memory model (single outstanding burst) ----------------
    reg [7:0] xmem [0:`EXT_BYTES-1];
    reg active = 1'b0, wr = 1'b0;
    reg [31:0] addr_cur = 32'd0;
    reg [7:0] beats_left = 8'd0;
    reg [15:0] cnt = 16'd0;
    wire x_cmd_ready = !active;
    wire x_rvalid = active && !wr && (cnt == 16'd0) && (beats_left != 8'd0);
    wire x_wready = active && wr && (cnt == 16'd0) && (beats_left != 8'd0);
    wire [31:0] x_rdata = {xmem[addr_cur+3], xmem[addr_cur+2], xmem[addr_cur+1], xmem[addr_cur]};

    always @(posedge clk) begin
        if (rst) begin
            active <= 1'b0; wr <= 1'b0; cnt <= 16'd0; beats_left <= 8'd0; addr_cur <= 32'd0;
        end else if (x_cmd_valid && x_cmd_ready) begin
            active <= 1'b1; wr <= x_cmd_write; addr_cur <= x_cmd_addr;
            beats_left <= x_cmd_beats; cnt <= `ROW_LAT_P;
        end else if (active) begin
            if (cnt != 16'd0) cnt <= cnt - 16'd1;
            else if (x_rvalid || (x_wready && x_wvalid)) begin
                if (x_wready && x_wvalid) begin
                    xmem[addr_cur]   <= x_wdata[7:0];
                    xmem[addr_cur+1] <= x_wdata[15:8];
                    xmem[addr_cur+2] <= x_wdata[23:16];
                    xmem[addr_cur+3] <= x_wdata[31:24];
                end
                addr_cur   <= addr_cur + 32'd4;
                beats_left <= beats_left - 8'd1;
                if (beats_left == 8'd1) active <= 1'b0;
            end
        end
    end

    // ---------------- DUT ----------------
    armse_top #(.NB(`NB_P), .LOGNB(`LOGNB_P), .A_DEPTH(`A_DEPTH_P), .B_DEPTH(`B_DEPTH_P),
                .O_DEPTH(`O_DEPTH_P), .PROG_DEPTH(4096)) dut (
        .clk(clk), .rst(rst), .go(go), .n_dma(`N_DMA), .n_cmp(`N_CMP),
        .h_we(h_we), .h_sel(h_sel), .h_addr(h_addr), .h_wdata(h_wdata),
        .busy(busy), .done(done), .cycles(cycles),
        .x_cmd_valid(x_cmd_valid), .x_cmd_ready(x_cmd_ready), .x_cmd_write(x_cmd_write),
        .x_cmd_addr(x_cmd_addr), .x_cmd_beats(x_cmd_beats), .x_rvalid(x_rvalid), .x_rdata(x_rdata),
        .x_wvalid(x_wvalid), .x_wdata(x_wdata), .x_wready(x_wready),
        .cmp_busy(cmp_busy), .cmp_wait(cmp_wait), .dma_busy(dma_busy), .dma_wait(dma_wait),
        .bytes_rd(bytes_rd), .bytes_wr(bytes_wr), .n_xfer(n_xfer), .bank_conflicts(conflicts));

    reg [127:0] tb_d [0:`N_DMA-1];
    reg [127:0] tb_c [0:`N_CMP-1];
    reg [31:0]  expc [0:`C_WORDS-1];
    integer i, errs, guard;
    reg [31:0] got;
    reg strict;

    initial begin
        strict = $test$plusargs("STRICT_CYC");
        $readmemh("ext.hex", xmem);
        $readmemh("dprog.hex", tb_d);
        $readmemh("cprog.hex", tb_c);
        $readmemh("expc.hex", expc);
        repeat (4) @(posedge clk);
        @(negedge clk); rst = 1'b0;
        for (i = 0; i < `N_DMA; i = i + 1) begin
            @(negedge clk); h_we = 1'b1; h_sel = 1'b0; h_addr = i; h_wdata = tb_d[i];
        end
        for (i = 0; i < `N_CMP; i = i + 1) begin
            @(negedge clk); h_we = 1'b1; h_sel = 1'b1; h_addr = i; h_wdata = tb_c[i];
        end
        @(negedge clk); h_we = 1'b0;
        @(negedge clk); go = 1'b1;
        @(negedge clk); go = 1'b0;
        guard = 0;
        while (!done && guard < 5000000) begin @(posedge clk); guard = guard + 1; end
        @(posedge clk);
        errs = 0;
        if (!done) begin $display("ERROR %s: timeout", `TEST_NAME); errs = errs + 1; end
        for (i = 0; i < `C_WORDS; i = i + 1) begin
            got = {xmem[`C_OFF+4*i+3], xmem[`C_OFF+4*i+2], xmem[`C_OFF+4*i+1], xmem[`C_OFF+4*i]};
            if (got !== expc[i]) begin
                if (errs < 10) $display("ERROR %s: C[%0d] got %h expected %h", `TEST_NAME, i, got, expc[i]);
                errs = errs + 1;
            end
        end
        if (bytes_rd !== `EXP_BYTES_RD) begin $display("ERROR bytes_rd %0d != %0d", bytes_rd, `EXP_BYTES_RD); errs = errs + 1; end
        if (bytes_wr !== `EXP_BYTES_WR) begin $display("ERROR bytes_wr %0d != %0d", bytes_wr, `EXP_BYTES_WR); errs = errs + 1; end
        if (n_xfer   !== `EXP_XFER)     begin $display("ERROR transfers %0d != %0d", n_xfer, `EXP_XFER); errs = errs + 1; end
        if (conflicts !== 32'd0)        begin $display("ERROR bank conflicts %0d", conflicts); errs = errs + 1; end
        $display("CYCLES %s measured=%0d model=%0d delta=%0d | cmp_busy=%0d (model %0d) dma_busy=%0d (model %0d) cmp_wait=%0d dma_wait=%0d",
                 `TEST_NAME, cycles, `EXP_CYCLES, $signed(cycles) - $signed(`EXP_CYCLES),
                 cmp_busy, `EXP_CMP_BUSY, dma_busy, `EXP_DMA_BUSY, cmp_wait, dma_wait);
        if (strict && cycles !== `EXP_CYCLES) begin $display("ERROR strict cycle mismatch"); errs = errs + 1; end
        if (errs == 0) $display("RESULT %s: PASS", `TEST_NAME);
        else           $display("RESULT %s: FAIL (%0d errors)", `TEST_NAME, errs);
        $finish;
    end
endmodule
